verify.cmd:
node --experimental-strip-types --no-warnings --import ./scripts/probe-ts.mjs -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ").replace(/\s+/g," ")
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
// ARM 1. THE DRIFT MECHANISM, kept exactly as this row first measured it: a stage label spelled by
// hand outside the manifest is how five files came to disagree about one word.
const files=["app/(main)/spaces/[slug]/settings/calendar/plan-board.tsx","lib/calendar/workflow-board.ts","components/spaces/calendar-workspace.tsx"]
let n=0
for(const f of files){const s=rd(f);if(s===null)process.exit(79);if(/[\u0027"]plan[\u0027"]\s*\?\s*[\u0027"]Planning[\u0027"]|stage === \u0027plan\u0027 \? \u0027Planning\u0027/.test(s))n++}
if(n>0)fail("stage labels are still declared by hand in "+n+" file(s) beside the manifest, so the views can drift apart again")
// ARM 2. WHERE THE AUDIENCE IS DECLARED. The word is a property of the MOUNT, never a flag on a row,
// so the team grid has to declare it and no member-facing mount may. Read as source because a .tsx
// cannot be imported under type stripping (scripts/probe-ts.mjs); the rendered halves are pinned by
// components/events/event-calendar.stage.render.test.tsx.
// SCAN-1345 (2026-11-27): the staff calendar retired; the team calendar is the suite, whose chips take
// their word from lib/calendar/planner/kinds.ts and name every kind, Planning included.
const kinds=rd("lib/calendar/planner/kinds.ts"),chip=rd("lib/calendar/planner/chip.ts")
const guest=rd("components/spaces/calendar-workspace.tsx"),popup=rd("components/spaces/space-events-popup.tsx")
if(kinds===null||chip===null||guest===null||popup===null)process.exit(79)
const TEAM=/audience=[\u0027"{]?\s*[\u0027"]?team/
if(!/planning: \{ key: \u0027planning\u0027, word: \u0027Planning\u0027/.test(norm(kinds))||!/look\.word/.test(norm(chip)))fail("the team calendar no longer names a Planning date on its chip, so a Planning date goes unnamed on the one surface that has kinds to tell apart")
for(const pair of [["the Space profile events popup",popup],["the workspace Guest preview",guest]]){
  if(TEAM.test(norm(pair[1])))fail("a member-facing calendar mount ("+pair[0]+") declares the team audience, so the public calendar prints a stage word on every chip where every row is an event (owner ruling 2026-09-23)")
}
Promise.all([import("@/lib/calendar/registry.ts"),import("@/lib/calendar/plans.ts")]).then(function(mods){
const reg=mods[0],plans=mods[1]
// ARM 3. THREE KINDS, THREE COLOURS. Planning, Private and To-dos all painted bg-info-bg, so three
// different things looked like one thing. Run the real read rather than grep the table.
const team=(o)=>reg.calendarPresentation(o,"team")
const member=(o)=>reg.calendarPresentation(o,"member")
const kinds=[{layer:"pencil",stage:"planning"},{layer:"private"},{layer:"todos"}]
const teamClasses=kinds.map((k)=>team(k).chipClass)
if(new Set(teamClasses).size!==3)fail("a Planning date, a Private entry and a To-do still resolve to the same grid chip: "+kinds.length+" kinds and "+new Set(teamClasses).size+" colour(s)")
// ARM 4. THE COLOURS STAY ON BOTH SURFACES (owner ruling 2026-09-23). The public calendar gives up
// the word and keeps the colour; giving up the colour too would be the original defect on the
// public half, with the missing word as cover.
const memberClasses=kinds.map((k)=>member(k).chipClass)
if(new Set(memberClasses).size!==3)fail("the public calendar lost the colours along with the word: the three kinds resolve to "+new Set(memberClasses).size+" colour(s) for a member")
if(/bg-primary\/10/.test(member({layer:"events"}).chipClass))fail("the events chip is back on the translucent bg-primary/10 ground, which measured 4.45:1 on the member shell")
// ARM 5. EVERY ROW CARRIES ITS WORD, and the 360px chip abbreviates rather than dropping it.
for(const pair of Object.entries(reg.CALENDAR_PRESENTATIONS)){
  if(!pair[1].word)fail("the calendar presentation for "+pair[0]+" carries no word, so a surface reading the table has only a colour to go on")
  if(!reg.calendarWord(pair[1],true))fail("the 360px chip drops the word for "+pair[0]+" instead of abbreviating it")
}
if(reg.CALENDAR_PRESENTATIONS.planning.shortWord==="Plan")fail("Planning abbreviates to Plan on a narrow grid, and capital-P Plan is the OBJECT rather than the stage (ADR-1523)")
// ARM 6. THE AUDIENCE LEVER, BOTH HALVES. Pinning only the team half is what would let the word
// creep back onto the public calendar unnoticed.
if(reg.calendarPrintsWord("team")!==true)fail("a team calendar prints no stage word, so a Planning date and a Private entry are told apart by colour alone")
if(reg.calendarPrintsWord("member")!==false)fail("the public Space calendar prints a stage word on every chip, where every row is an event and the word separates nothing (owner ruling 2026-09-23)")
// ARM 7. ONE WORD FOR A STAGE, whichever table it is read from. This is arm 1 consequence rather
// than its spelling: a Plan and the dates on it are the same three steps under two column names.
for(const pair of [["pencil","pencil"],["plan","planning"],["production","production"],["cancelled","cancelled"]]){
  const word=reg.CALENDAR_PRESENTATIONS[pair[1]].word
  if(plans.planStageLabel(pair[0])!==word)fail("a Plan stage and the date on it say different words: planStageLabel("+pair[0]+") is "+plans.planStageLabel(pair[0])+" and the calendar registry says "+word)
}
if(plans.planStagePresentation("plan").chipClass!==team({stage:"planning"}).chipClass)fail("a Workflow card and the grid chip for the same Plan stage take different colours")
}).catch((e)=>{console.error(String(e&&e.message?e.message:e));process.exit(1)})'
